            return false;
        }
        nivel = nuevo;
        return true;
    }
}

int main() {
    const bool aceptado = deposito::poner(12);
    std::cout << aceptado << ':' << deposito::nivel << ';';
    deposito::nivel = 12;
    std::cout << deposito::nivel << ':' << deposito::capacidad;
    return 0;
}

