#include <iostream>

namespace sala_a {
    constexpr int capacidad = 8;
    int ocupadas = 3;
}

namespace sala_b {
    constexpr int capacidad = 12;
    int ocupadas = 7;
}

bool trasladar(int origen, int cantidad) {
    if ((origen != 0 && origen != 1) || cantidad < 1 || cantidad > 4) {
        return false;
    }
    if (origen == 0) {
        if (cantidad > sala_a::ocupadas ||
            cantidad > sala_b::capacidad - sala_b::ocupadas) {
            return false;
        }
        sala_a::ocupadas -= cantidad;
        sala_b::ocupadas += cantidad;
    } else {
        if (cantidad > sala_b::ocupadas ||
            cantidad > sala_a::capacidad - sala_a::ocupadas) {
            return false;
        }
        sala_b::ocupadas -= cantidad;
        sala_a::ocupadas += cantidad;
    }
    return true;
}

int main() {
    int numeroDeOrdenes = 0;
    if (!(std::cin >> numeroDeOrdenes) ||
        numeroDeOrdenes < 1 || numeroDeOrdenes > 12) {
        std::cout << "Datos invalidos\n";
        return 0;
    }
    for (int i = 0; i < numeroDeOrdenes; ++i) {
        int origen = 0;
        int cantidad = 0;
        if (!(std::cin >> origen >> cantidad)) {
            std::cout << "Datos invalidos\n";
            return 0;
        }
        const bool aceptado = trasladar(origen, cantidad);
        std::cout << (aceptado ? "Aceptado" : "Rechazo");
        std::cout << ";A:" << sala_a::ocupadas
                  << ";B:" << sala_b::ocupadas << '\n';
    }
    std::cout << "Total:" << sala_a::ocupadas + sala_b::ocupadas << '\n';
    return 0;
}
